"""Probe tool: send a tree of files directly to packignore service and print result.

Usage:
  python3 probe.py <<EOF
  /path  content
  /another/.packignore  *.log
  /another/x.log  ignored
  EOF

Or pass a dict directly via -c "<pyexpr>".
"""
import json, os, sys, urllib.request, urllib.error

URL = os.environ["PACKIGNORE_URL"]


def ignored(files):
    req = urllib.request.Request(URL + "/ignored", data=json.dumps({"files": files}).encode(),
                                 headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            return json.load(resp)["ignored"]
    except urllib.error.HTTPError as e:
        body = e.read().decode()
        return {"ERROR": body}


if __name__ == "__main__":
    if len(sys.argv) > 1 and sys.argv[1] == "-c":
        files = eval(sys.argv[2])
    else:
        files = {}
        for line in sys.stdin:
            line = line.rstrip("\n")
            if not line:
                continue
            path, _, content = line.partition("\t")
            files[path] = content if content else None
    print(json.dumps(ignored(files), indent=2))

